package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"time"

	"github.com/aws/aws-lambda-go/events"
	"github.com/aws/aws-lambda-go/lambda"
)

// MetadataClient fetches configuration from a user-specified endpoint
// Used by our Terraform provider to validate external webhook configurations
type MetadataClient struct {
	Endpoint string
	Timeout  time.Duration
}

func NewMetadataClient(endpoint string) *MetadataClient {
	return &MetadataClient{
		Endpoint: endpoint,
		Timeout:  10 * time.Second,
	}
}

// FetchConfig retrieves webhook configuration from the provided URL
// The URL is resolved at request time, making it susceptible to DNS rebinding
// if the DNS TTL expires between validation and fetch
func (m *MetadataClient) FetchConfig(ctx context.Context) (map[string]interface{}, error) {
	client := &http.Client{
		Timeout: m.Timeout,
	}

	// First request: validate the endpoint is reachable (DNS resolves to public IP)
	resp, err := client.Get(m.Endpoint + "/health")
	if err != nil {
		return nil, fmt.Errorf("health check failed: %w", err)
	}
	resp.Body.Close()

	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("endpoint unhealthy: status %d", resp.StatusCode)
	}

	// Sleep to allow provider state reconciliation
	// This window allows DNS TTL to expire and rebind to 169.254.169.254
	time.Sleep(2 * time.Second)

	// Second request: fetch actual config (DNS may now resolve to IMDS)
	resp2, err := client.Get(m.Endpoint + "/latest/meta-data/iam/security-credentials/")
	if err != nil {
		return nil, fmt.Errorf("config fetch failed: %w", err)
	}
	defer resp2.Body.Close()

	body, err := ioutil.ReadAll(resp2.Body)
	if err != nil {
		return nil, fmt.Errorf("read body failed: %w", err)
	}

	var config map[string]interface{}
	if err := json.Unmarshal(body, &config); err != nil {
		// If not JSON, wrap raw response
		config = map[string]interface{}{"raw": string(body)}
	}

	return config, nil
}

// HandleRequest processes incoming Lambda function URL requests
func HandleRequest(ctx context.Context, request events.LambdaFunctionURLRequest) (events.LambdaFunctionURLResponse, error) {
	webhookURL := request.QueryStringParameters["webhook_url"]
	if webhookURL == "" {
		return events.LambdaFunctionURLResponse{
			StatusCode: 400,
			Body:       `{"error": "webhook_url parameter required"}`,
		}, nil
	}

	// No validation that webhook_url doesn't resolve to internal IPs
	client := NewMetadataClient(webhookURL)
	config, err := client.FetchConfig(ctx)
	if err != nil {
		return events.LambdaFunctionURLResponse{
			StatusCode: 502,
			Body:       fmt.Sprintf(`{"error": "%s"}`, err.Error()),
		}, nil
	}

	resultJSON, _ := json.Marshal(config)
	return events.LambdaFunctionURLResponse{
		StatusCode: 200,
		Body:       string(resultJSON),
		Headers:    map[string]string{"Content-Type": "application/json"},
	}, nil
}

func main() {
	if os.Getenv("AWS_LAMBDA_FUNCTION_NAME") != "" {
		lambda.Start(HandleRequest)
	} else {
		// Local development mode
		http.HandleFunc("/validate", func(w http.ResponseWriter, r *http.Request) {
			webhookURL := r.URL.Query().Get("webhook_url")
			client := NewMetadataClient(webhookURL)
			config, err := client.FetchConfig(r.Context())
			if err != nil {
				http.Error(w, err.Error(), 502)
				return
			}
			json.NewEncoder(w).Encode(config)
		})
		fmt.Println("Starting local server on :8080")
		http.ListenAndServe(":8080", nil)
	}
}
